/**
 *
 * TooltipPopup is a component that displays the popup of a tooltip.
 *
 * [Live Demo](https://www.primereact.org/tooltip/)
 *
 * @module TooltipPopup
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UseMotionProps } from '@primereact/types/headless/motion';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { TooltipRootInstance } from './TooltipRoot.types';
/**
 * Defines passthrough(pt) options type in TooltipPopup component.
 */
export type TooltipPopupPassThroughType<E> = PassThroughType<TooltipPopupInstance, E>;
/**
 * Defines passthrough(pt) options of TooltipPopup component.
 */
export interface TooltipPopupPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: TooltipPopupPassThroughType<React.HTMLAttributes<HTMLButtonElement>>;
}
/**
 * Defines valid properties in TooltipPopup component.
 */
export interface TooltipPopupProps extends BaseComponentProps<TooltipPopupInstance, unknown, TooltipPopupPassThrough> {
    /**
     * Used to apply motion to the popup element. It accepts the same properties as the useMotion hook.
     */
    motionProps?: UseMotionProps | undefined;
}
/**
 * Defines valid state in TooltipPopup component.
 */
export interface TooltipPopupState {
}
/**
 * Defines the methods and properties exposed by TooltipPopup component.
 */
export interface TooltipPopupExposes {
    /**
     * The Tooltip component instance.
     */
    tooltip: TooltipRootInstance | undefined | null;
}
/**
 * Instance of TooltipPopup component.
 */
export type TooltipPopupInstance = ComponentInstance<TooltipPopupProps, TooltipPopupState, TooltipPopupExposes>;
